def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        op_type = op[0]
        t = op[1]
        key = op[2]

        # Remove expired entries
        expired_keys = []
        for k, (v, write_time) in cache.items():
            if write_time + ttl <= t:
                expired_keys.append(k)
        for k in expired_keys:
            del cache[k]

        if op_type == 'put':
            value = op[3]

            # If key already exists, remove it first
            if key in cache:
                del cache[key]
            # If cache is at capacity and we're adding a new key, evict LRU
            elif len(cache) >= capacity:
                # Remove the first (least recently used) item
                cache.popitem(last=False)

            # Add the new entry (most recently used)
            cache[key] = (value, t)

        elif op_type == 'get':
            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                # Move to end (most recently used)
                del cache[key]
                cache[key] = (value, write_time)
            else:
                results.append(-1)

    return results

